def count_squares(lines):
    def is_square(vertex):
        # Check if the four surrounding characters are '+'
        return all(lines[vertex[0] + dy][vertex[1] + dx] == '+' for dy, dx in [(-1, 0), (0, -1), (1, 0), (0, 1)])

    count = 0
    for i in range(len(lines)):
        for j in range(len(lines[i])):
            if lines[i][j] == '+':
                if is_square((i, j)):
                    count += 1
    return count

