def bingo(array):
    letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    bingo_letters = ['B', 'I', 'N', 'G', 'O']

    collected_letters = [letters[num - 1] for num in array if num >= 1 and num <= 26]

    if sorted(collected_letters) == bingo_letters:
        return "WIN"
    else:
        return "LOSE"

