def duck_shoot(ammo, aim, ducks):
    result = []
    for i, duck in enumerate(ducks):
        if ammo > 0 and aim >= (i / len(ducks)):
            result.append('X')
            ammo -= 1
        else:
            result.append(duck)
    return ''.join(result)

