def bird_code(arr):
    result = []
    for name in arr:
        # Split the name into words using space and hyphen as delimiters
        words = name.split(' ')
        num_words = len(words)
        code = ""

        # Determine the code based on the number of words
        if num_words == 1:
            code = words[0][:4].upper()
        elif num_words == 2:
            code = words[0][:2] + words[1][:2].upper()
        elif num_words == 3:
            code = words[0][0] + words[1][0] + words[2][:2].upper()
        elif num_words == 4:
            code = ''.join(word[0] for word in words).upper()

        # Append the code to the result array
        result.append(code)

    return result

