def shoot(results):
    # Initialize total hits for Pete and Phil
    pete_hits = 0
    phil_hits = 0

    # Iterate through each round
    for round in results:
        # Check hits for Pete and Phil based on the boolean value
        if round[1]:
            pete_hits += round[0]['P1'].count('X') * 2 + round[0]['P2'].count('X') * 2
            phil_hits += round[0]['P1'].count('O') * 2 + round[0]['P2'].count('O') * 2
        else:
            pete_hits += round[0]['P1'].count('X') * 1 + round[0]['P2'].count('X') * 1
            phil_hits += round[0]['P1'].count('O') * 1 + round[0]['P2'].count('O') * 1

    # Compare totals and determine the winner
    if pete_hits > phil_hits:
        return 'Pete Wins!'
    elif phil_hits > pete_hits:
        return 'Phil Wins!'
    else:
        return 'Draw!'

