def cat_mouse(x, j):
    # Find the positions of C, D, and m
    pos_C = x.find('C')
    pos_D = x.find('D')
    pos_m = x.find('m')

    # Check if all characters are present
    if pos_C == -1 or pos_D == -1 or pos_m == -1:
        return 'boring without all three'

    # Calculate the distance between the cat and the mouse
    distance = abs(pos_C - pos_m)

    # Check if the cat can catch the mouse
    if distance <= j:
        return 'Caught!'
    else:
        # Check if the dog is in the way of the cat's jump
        if pos_C > pos_D and pos_m > pos_D and pos_C - pos_D < distance:
            return 'Protected!'
        else:
            return 'Escaped!'

