    }

    # Define the number of marbles of each color that are smooth or bumpy
    marbles_by_texture = {
        'red': {'bumpy': 4, 'smooth': 1},
        'yellow': {'bumpy': 2, 'smooth': 1},
        'green': {'bumpy': 1, 'smooth': 1}
    }

    # Calculate the probability
    probability = marbles_by_texture[color][texture] / total_marbles[color]

    # Format the probability to two decimal places as a string
    probability_str = f"{probability:.2f}"

    return probability_str

