def hamster_me(code, message):
    # Initialize a dictionary to store the mapping of letters to numbers
    letter_to_number = {}
    current_number = 1

    # Assign numbers to each letter in the code
    for letter in code:
        if letter not in letter_to_number:
            letter_to_number[letter] = current_number
            current_number += 1

    # Iterate through the message to assign numbers to each letter
    encrypted_message = []
    for char in message:
        if char in letter_to_number:
            encrypted_message.append(str(letter_to_number[char]))
        else:
            # Find the next available number in the code
            next_number = current_number
            while next_number in letter_to_number:
                next_number += 1
            letter_to_number[char] = next_number
            encrypted_message.append(str(next_number))
            current_number = next_number

    # Join the numbers to form the encrypted string
    return ''.join(encrypted_message)

