def changer(string):
    vowels = set('aeiouAEIOU')

    def process_char(c):
        if c.isalpha():
            # Get the ASCII value of the character
            ascii_val = ord(c)
            # Calculate the next character, wrapping around if necessary
            next_char_ascii = (ascii_val - 96) % 26 + 96
            # Convert back to a character
            next_char = chr(next_char_ascii)
            # Check if the next character is a vowel
            if next_char in vowels:
                # If it's a vowel, make it uppercase
                return next_char.upper()
            else:
                # If it's a consonant, make it lowercase
                return next_char.lower()
        else:
            # If it's not a letter, return it unchanged
            return c

    # Process each character in the string
    processed_string = ''.join(process_char(c) for c in string)
    return processed_string

