def repeat_sequence_len(a0):
    def F(N):
        return sum(int(digit) ** 2 for digit in str(N))

    seen = set()
    current = a0

    while current not in seen:
        seen.add(current)
        current = F(current)

    repeat_start = current
    repeat_end = None

    while True:
        current = F(current)
        if current == repeat_start:
            break
        seen.add(current)

    repeat_length = len(seen)

    return repeat_length

