def solve(s):
    # Initialize an empty list to store number groupings
    number_groups = []

    # Initialize an empty string to build number groups
    current_number = ""

    # Iterate through each character in the string
    for char in s:
        # If the character is a digit, add it to the current number group
        if char.isdigit():
            current_number += char
        else:
            # If the current number group is not empty, convert it to an integer and add to the list
            if current_number:
                number_groups.append(int(current_number))
            # Reset the current number group
            current_number = ""

    # If there's a number group left after the loop, add it to the list
    if current_number:
        number_groups.append(int(current_number))

    # Return the maximum number found in the list
    return max(number_groups)

