    position = key_press_count % 15

    # Classify the key based on its position
    if position <= 5:
        return "white"
    else:
        return "black"

def get_score(arr) -> int:
    level = 0
    total_score = 0
    cleared_lines = 0

    for line in arr:
        cleared_lines += line
        level = cleared_lines // 10

    for i in range(cleared_lines):
        score = 0
        if i < 4:
            score = (level + 1) * (i + 1) * 40
        else:
            score = (level + 1) * (4 * 40) + (i - 3) * 100
        total_score += score

    return total_score

